style.css:
@-moz-document url-prefix("https://www.rolimons.com/") {
*,
*::before,
*::after,
button,
.btn,
input,
textarea,
select,
.alert,
.card,
.value-stat-box,
.d-none > .img-responsive,
#filter-min,
#filter-max {
  border-radius: 10px !important;
}

/* cards */
.mix_item {
  border-radius: 10px !important;
  overflow: hidden;
}
.mix_item .item_card_img_container {
  border: 0;
}

/* square-only elements */
svg,
.navbar,
.system_item_tag_icon,
.shadow_md_35 .position-relative,
.shadow_md_35 .global_item_search_system_item_tag_icon,
.shadow_md_35 .d-flex > .global_item_search_stat_data,
.mix_item .item_card_img_container,
.mix_item .d-flex > .text-light,
#player_value,
#player_rap,
#history_chart_notice > svg,
.page_title_offsite_link_icon > svg,
.odd > td,
.dataTables_scrollHeadInner .sorting,
.dataTables_scrollHeadInner .sorting_disabled,
.swiper-slide-active .wishlist_slider_main_image_container,
.swiper-slide-next .wishlist_slider_main_image_container,
.wishlist_slider_card .wishlist_slider_main_image_container,
.pb-2 .std_item_card_img_bkgnd_gradient,
.odd .premium_icon,
.even .premium_icon,
#stats-pane-overview div > .d-flex .card-title {
  border-radius: 0 !important;
}

/* top rounded */
.shadow > .pt-2,
.bg-dark {
  border-radius: 10px 10px 0 0 !important;
}

/* bottom rounded */
.stats_box {
  border-radius: 0 0 10px 10px !important;
}

/* left rounded */
#global_player_search_textbox,
#global_item_search_textbox,
#inventory_search_textbox,
#catalog_search_textbox,
#trade_calculator_page_search_textbox,
#filter-category-dropdown,
.px-xl-2 {
  border-radius: 10px 0 0 10px !important;
}

/* right rounded */
#global_player_search_textbox_clear,
#global_item_search_textbox_clear,
#inventory_search_textbox_clear,
#catalog_search_textbox_clear,
#trade_calculator_page_search_textbox_clear,
#deal-custom-percentage,
.btn-light {
  border-radius: 0 10px 10px 0 !important;
}

/* deal badges */
.deal_bg_color_poor,
.deal_bg_color_uncommon,
.deal_bg_color_rare,
.deal_bg_color_epic {
  border-radius: 0 10px 0 0 !important;
}

/* special cases */
.global_player_search_mix_item .std_item_card_img_bkgnd_gradient {
  border-radius: 0 0 16px 10px !important;
}

.highcharts-label > .highcharts-label-box {
  border-radius: 10px !important;
}

.card,
.panel,
.box {
  box-shadow: 0 4px 16px rgba(0,0,0,0.5) !important;
}

.switch-slider {
  border-radius: 7px !important;
}

.highcharts-button-box {
  rx: 7 !important;
  ry: 7 !important;
}
.highcharts-label {
  rx: 7 !important;
  ry: 7 !important;
}

.highcharts-label > .highcharts-label-box {
  rx: 7 !important;
  ry: 7 !important;
}
.show > .site_navbar_item {
  border-radius: 0px !important;
}
.nav-item > .dropdown-menu {
  border-radius: 0 0 10px 10px !important;
}
#navbarTradingDropdown {
  border-radius: 0px !important;
}
#navbarCatalogDropdown {
  border-radius: 0px !important;
}
#navbarUgcDropdown {
  border-radius: 0px !important;
}
#navbarPlayersDropdown {
  border-radius: 0px !important;
}
#navbarGamesDropdown {
