}
#navbarPlayerDropdown {
  border-radius: 0px !important;
}
#navbarMoreFeaturesDropdown {
  border-radius: 0px !important;
}
.ml-xl-5 .active {
  border-radius: 0 0 10px 10px !important;
}
.ml-xl-5 > .nav-item:nth-child(2) > .nav-link {
  border-radius: 0 0 10px 10px !important;
}
.ml-xl-5 > .nav-item:nth-child(3) > .nav-link {
  border-radius: 0 0 10px 10px !important;
}
#history_chart_tab {
  border-radius: 10px 10px 0 0 !important;
}
#value_chart_tab {
  border-radius: 10px 10px 0 0 !important;
}
#copies_chart_tab {
  border-radius: 10px 10px 0 0 !important;
}
#ownership_chart_tab {
  border-radius: 10px 10px 0 0 !important;
}
#hoarding_chart_tab {
  border-radius: 10px 10px 0 0 !important;
}
#bc_owner_table_tab_button > .nav-link {
