	display: none;
}
.suggested-roblox-assets-slider-button-next {
	display: none;
}
.suggested-ugc-assets-slider-button-next {
	display: none;
}

/* make all dropdown items flat */
.nav-item .dropdown-menu .nav-link {
    border-radius: 0 !important;
}

/* round only the bottom of the last item */
.nav-item .dropdown-menu .nav-link:last-child {
    border-radius: 0 0 10px 10px !important;
}

.highcharts-series-1 {
    stroke-linejoin: round;   /* makes corners of line smooth */
    stroke-linecap: round;    /* makes line ends rounded */
}

